#pragma once

#include <stdbool.h>
#include <stddef.h>

// IANA zone name -> POSIX TZ rule, sorted by name (tz_db.c is generated by
// tools/gen_tz_db.py). Pure data, so the native UI build uses it too.
typedef struct {
    const char *name;
    const char *posix;
} tz_entry_t;

extern const tz_entry_t tz_db[];
extern const size_t tz_db_count;

// Index of `name` in tz_db, or -1.
int tz_db_find(const char *name);

// Makes `name` the local zone for localtime(); false (zone unchanged) if
// it isn't in tz_db.
bool tz_apply(const char *name);

// Fixed-offset fallback for a zone missing from tz_db: east-positive
// seconds, as geolocation APIs report them.
void tz_apply_offset(int offset_s);
